import{_ as s,o as t,c as a,a2 as n}from"./chunks/framework.SiCi1vp-.js";const k=JSON.parse('{"title":"Connect an MCP client","description":"","frontmatter":{},"headers":[],"relativePath":"mcp.md","filePath":"mcp.md","lastUpdated":1793869287000}'),i={name:"mcp.md"};function o(h,e,r,l,d,c){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="connect-an-mcp-client" tabindex="-1">Connect an MCP client <a class="header-anchor" href="#connect-an-mcp-client" aria-label="Permalink to &quot;Connect an MCP client&quot;">​</a></h1><p>An external MCP client can create sessions, read their transcripts, and send messages to your agents. Prefer remote HTTP with browser sign-in; use a local stdio process with a personal API token when your client needs a local process. Both expose the same tool names.</p><h2 id="remote-http" tabindex="-1">Remote HTTP <a class="header-anchor" href="#remote-http" aria-label="Permalink to &quot;Remote HTTP&quot;">​</a></h2><p>AgentHub serves MCP at <code>https://hub.example.com/mcp</code> using <strong>Streamable HTTP</strong> and <strong>OAuth 2.1</strong>. AgentHub federates browser sign-in to your instance&#39;s OIDC provider. The endpoint is <strong>off by default</strong>.</p><h3 id="enable-the-endpoint" tabindex="-1">Enable the endpoint <a class="header-anchor" href="#enable-the-endpoint" aria-label="Permalink to &quot;Enable the endpoint&quot;">​</a></h3><p>Add this to your Helm values file and apply it using your normal <a href="/docs/upgrading">upgrade procedure</a>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">mcp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  publicUrl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://hub.example.com&quot;</span></span></code></pre></div><p><code>mcp.publicUrl</code> is optional when your ingress host already supplies the correct HTTPS origin. It is the public origin, without <code>/mcp</code>, and becomes the OAuth issuer and token audience. The client and browser must be able to reach it.</p><p>Allow <code>https://hub.example.com/connect/oidc-callback</code> as a redirect URI for your instance&#39;s OIDC client. This is separate from the web UI&#39;s <code>/auth/callback</code> URI.</p><h3 id="copy-setup-from-settings" tabindex="-1">Copy setup from Settings <a class="header-anchor" href="#copy-setup-from-settings" aria-label="Permalink to &quot;Copy setup from Settings&quot;">​</a></h3><p>When enabled, <strong>Settings → Connect to AgentHub</strong> provides the instance&#39;s exact endpoint, a Claude Code command, a Claude Desktop connector URL and Cursor JSON, each with a copy button. Disabled endpoints show an <code>mcp.enabled</code> hint only to administrators.</p><h3 id="connect-and-authenticate" tabindex="-1">Connect and authenticate <a class="header-anchor" href="#connect-and-authenticate" aria-label="Permalink to &quot;Connect and authenticate&quot;">​</a></h3><p>In Claude Code:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --transport</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://hub.example.com/mcp</span></span></code></pre></div><p>Run <code>/mcp</code> and authenticate in the browser. Sign in to the hub and approve the client&#39;s access. Other clients need remote HTTP transport and OAuth support; enter the same endpoint in their MCP settings. Client registration is automatic, and the authorization flow uses PKCE. Tools act as the user who approved the client and follow the hub&#39;s access checks.</p><p><strong>Claude Desktop:</strong> open Settings → Connectors → Add custom connector. Use the name AgentHub and paste the remote MCP URL from the hub&#39;s Settings page. Connect and sign in in the browser. The connector service must be able to reach your instance URL.</p><p><strong>Cursor:</strong> paste the configuration from the hub into <code>~/.cursor/mcp.json</code> or the project&#39;s <code>.cursor/mcp.json</code>, then connect in MCP settings:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;agenthub&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://hub.example.com/mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Without OIDC, API-key mode asks for the instance key on the browser consent screen. Only explicit insecure development mode skips login and issues a token for the shared <code>dev</code> user. The endpoint stays off by default because enabling it exposes an authorization server and anonymous client registration, and missing OIDC alone does not disable it. Enable it deliberately after configuring HTTPS and the identity-provider callback.</p><h2 id="local-stdio" tabindex="-1">Local stdio <a class="header-anchor" href="#local-stdio" aria-label="Permalink to &quot;Local stdio&quot;">​</a></h2><p>The stdio server is shipped as source under <a href="https://github.com/open-agenthub/open-agenthub/tree/main/mcp/agenthub" target="_blank" rel="noreferrer"><code>mcp/agenthub</code></a> in the main repository; the package name is <code>mcp-agenthub</code>. It uses a personal API token from <strong>Settings → API tokens</strong>, rather than the remote endpoint&#39;s OAuth flow.</p><p>Clone the repository locally, then install its dependencies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open-agenthub/mcp/agenthub</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span></code></pre></div><p>Configure your MCP client to launch Node with the absolute path to <code>server.mjs</code> and set <code>AGENTHUB_URL</code> and <code>AGENTHUB_TOKEN</code> in the client&#39;s environment configuration:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;agenthub&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/absolute/path/open-agenthub/mcp/agenthub/server.mjs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;AGENTHUB_URL&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://hub.example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;AGENTHUB_TOKEN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;personal-api-token&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Adapt this example to your client&#39;s configuration format. The token starts with <code>oah_</code>; keep the real value local. The stdio server calls the token-authenticated API and does not require <code>mcp.enabled</code> or an OIDC browser login.</p><h2 id="sessions-shared-with-you" tabindex="-1">Sessions shared with you <a class="header-anchor" href="#sessions-shared-with-you" aria-label="Permalink to &quot;Sessions shared with you&quot;">​</a></h2><p>Available with the 1.15.0 release and an active sharing license. Both the remote server and the personal-token stdio server include named shares in <code>session_list</code> and <code>agents_list</code>. This includes shares inherited from a parent session and shares through a project. Entries show <code>owner</code>, <code>accessRole</code> and <code>canWrite</code>, so your client can identify which sessions it may message.</p><p>Use <code>session_get</code> for sanitized status. A Viewer can read status; a Collaborator can also use <code>agent_send</code> with normal delivery. Shared sessions reject <code>priority</code> and <code>interrupt</code>. These messages are attributed to the sender&#39;s account and audited. A share gives no authority to delete or manage another owner&#39;s session, change its credentials, or clear its context. Removing a share takes effect on the next tool call.</p><p>Legacy chat sessions reject normal <code>agent_send</code> messages with guidance to type into the session&#39;s conversation. Open the conversation as the owner or a Collaborator and send the message there. An owner can also use <code>agent_send</code> with priority for a running legacy chat session.</p><h2 id="use-a-share-link" tabindex="-1">Use a share link <a class="header-anchor" href="#use-a-share-link" aria-label="Permalink to &quot;Use a share link&quot;">​</a></h2><p><code>share_link_read</code> accepts a share URL or its token in the <code>link</code> argument and returns <code>session</code> (sanitized status and the link&#39;s role) plus <code>history</code> (a page of conversation). For example, ask your client to call:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;link&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://hub.example.com/shared/&lt;share-token&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;offset&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;max&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Use <code>history.nextOffset</code> as the next <code>offset</code> to continue reading. <code>max</code> counts conversation entries for <code>history.source = &quot;native&quot;</code>, or characters for <code>&quot;scrollback&quot;</code>. Omit <code>offset</code> to start at the beginning; <code>-1</code> requests the latest window.</p><p>A Collaborator link also permits <code>share_link_send</code> with <code>link</code> and <code>message</code>. This queues a normal message for a terminal-mode session, attributed and audited as <strong>via share link</strong>. For a legacy chat session, open the Collaborator link in your browser and type into the conversation. Viewer links are read only. Revoked or expired links answer not found. Link tools provide the same role authority as the browser share view; they do not add the session to your named shares or permit management.</p><p>For a client without an account, connect its HTTP MCP transport to <code>https://hub.example.com/mcp/shared</code>. This endpoint exposes only <code>share_link_read</code> and <code>share_link_send</code>; the usual authenticated <code>/mcp</code> endpoint also has both tools. The server must have remote MCP enabled. A local stdio client can use these tools with <code>AGENTHUB_URL</code> and no <code>AGENTHUB_TOKEN</code>; other session tools still require a personal token.</p><p>Treat the link as a bearer secret: anyone holding it has its role. Pass it only as a tool argument. The stdio bridge sends it in a POST body rather than an access-log URL. Keep client argument and HTTP body logging off for these calls, and revoke the link if it is disclosed.</p><h2 id="first-checks" tabindex="-1">First checks <a class="header-anchor" href="#first-checks" aria-label="Permalink to &quot;First checks&quot;">​</a></h2><p>Ask the connected client to list your sessions with <code>session_list</code>. Use <code>session_logs</code> or <code>session_transcript</code> to read agent output; pod logs primarily show runtime startup. <code>agents_list</code> discovers agents and <code>agent_send</code> sends messages. Creating or changing sessions is a separate action from listing them.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>HTTP 503: MCP endpoint disabled</td><td>Enable <code>mcp.enabled</code> and apply the Helm values.</td></tr><tr><td>HTTP 401 on remote HTTP</td><td>Complete the client&#39;s OAuth sign-in.</td></tr><tr><td>Identity provider reports <code>invalid_redirect_uri</code></td><td>Register the exact public <code>/connect/oidc-callback</code> URI.</td></tr><tr><td>Wrong issuer or unreachable authorization URL</td><td>Check <code>mcp.publicUrl</code>, ingress and HTTPS reachability.</td></tr><tr><td>Stdio authentication fails</td><td>Check <code>AGENTHUB_URL</code> and the personal API token in the client environment.</td></tr></tbody></table><p>MCP controls sessions; <a href="/docs/local-sessions">local continuation</a> uses separate archive helpers. For the full tool reference and OAuth endpoints, see the <a href="https://github.com/open-agenthub/open-agenthub/blob/main/docs/mcp-server.md" target="_blank" rel="noreferrer">MCP server documentation</a>.</p>`,41)])])}const u=s(i,[["render",o]]);export{k as __pageData,u as default};
